// 原开工和终结事实永久相连；继续入口不猜普通旅行、不制造完成或重新开始会面。
#include "personal_appointment_progress.hpp"
#include "resident/kernel/common_fact_prefix.hpp"
#include "personal_appointment_detail.hpp"
#include "personal_appointment_time2.hpp"
#include "personal_appointment_boundary.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {namespace {
using Result=Outcome<std::optional<PersonalAppointmentActionSource>>;
// 完整来源的精确header和真实插入顺序是业务读边界，不依赖可被裁剪的Command history。
bool header(const CommonStore& common,const StableId& id,const StableId& kind){const auto* h=common.state().facts.find(id);return h&&h->id==id&&h->kind==kind&&h->domain==personal_appointment_module&&appointment_detail::serial(id,kind,common.state().next_instance_id).has_value();}
bool before(const CommonStore& common,const StableId& first,const StableId& last){const auto* first_header=common.state().facts.find(first);const auto* last_header=common.state().facts.find(last);if(!first_header||!last_header)return false;const auto a=read_actual_common_fact_position(common,*first_header),b=read_actual_common_fact_position(common,*last_header);return a.ok&&b.ok&&a.value<b.value;}
Result fail(const StableId& code,const StableId& id){return {false,{},common_failure(code,id).error};}
}
Outcome<std::optional<PersonalAppointmentActionSource>> query_personal_appointment_action(const CommonStore& common,const PersonalAppointmentState& state,const StableId& actor,const StableId& action_id,const PersonalAppointmentTime2Context*exact){
    if(state.version==2){
     if(!exact)return {false,{},common_failure("PersonalAppointmentExactProgressReadRequired",action_id,ErrorKind::unsupported_capability).error};if(&exact->common!=&common||&exact->state!=&state)return {false,{},common_failure("PersonalAppointmentProgressCandidateMismatch",action_id,ErrorKind::internal).error};
     auto valid=validate_personal_appointment_time2(*exact);if(!valid.ok)return {false,{},valid.error};valid=validate_personal_appointment_cached_results(common,&state);if(!valid.ok)return {false,{},valid.error};
     if(!common.actor(actor)||action_id.empty())return fail("InvalidPersonalAppointmentActionQuery",actor);const PersonalAppointmentStarted*start=nullptr;for(const auto&row:state.started.rows())if(row.second.action_id==action_id){if(start)return fail("DuplicatePersonalAppointmentAction",action_id);start=&row.second;}
     if(!start){const auto*a=common.action(action_id);if(a&&a->kind==personal_appointment_action_kind)return fail("PersonalAppointmentActionSourceRequired",action_id);return {true,std::nullopt,{}};}if(start->contact.actor_id!=actor)return {true,std::nullopt,{}};
     PersonalAppointmentActionSource out;out.source_identity=common.state().identity;out.actor_id=actor;out.appointment_id=start->appointment_id;out.action_id=action_id;out.started_fact_id=start->fact_id;out.contact=start->contact;out.start_tick=start->contact.tick;
     auto at=read_personal_appointment_source_moment(*exact,{personal_appointment_module,personal_appointment_started_kind,start->fact_id},2);if(!at.ok)return {false,{},at.error};out.actual_started_at=std::move(at.value);
     const auto*f=appointment_detail::finish(state,start->appointment_id);if(f){out.finished_fact_id=f->fact_id;out.finished_tick=f->tick;out.success=f->success;out.reason=f->reason;out.status=f->success?"fulfilled":"interrupted";auto end=read_personal_appointment_source_moment(*exact,{personal_appointment_module,personal_appointment_finished_kind,f->fact_id},2);if(!end.ok)return {false,{},end.error};out.actual_finished_at=std::move(end.value);}else{const auto*a=common.action(action_id);if(!a)return fail("PersonalAppointmentActualActionMissing",action_id);out.status="active";out.remaining_ticks=a->remaining_ticks;}return {true,std::move(out),{}};
    }
    if(exact)return {false,{},common_failure("PersonalAppointmentProgressVersionMismatch",action_id,ErrorKind::internal).error};
    if(!common.actor(actor)||action_id.empty())return fail("InvalidPersonalAppointmentActionQuery",actor);const auto* current=common.action(action_id);const PersonalAppointmentStarted* start=nullptr;
    for(const auto& row:state.started.rows())if(row.second.action_id==action_id){if(start)return fail("DuplicatePersonalAppointmentAction",action_id);start=&row.second;}
    if(!start){if(current&&current->kind==personal_appointment_action_kind)return fail("PersonalAppointmentActionSourceRequired",action_id);return {true,std::nullopt,{}};}
    if(start->contact.actor_id!=actor)return {true,std::nullopt,{}};const auto* accepted=state.accepted.find(start->appointment_id);const auto action_number=appointment_detail::serial(action_id,"action",common.state().next_instance_id),start_number=appointment_detail::serial(start->fact_id,personal_appointment_started_kind,common.state().next_instance_id);
    if(state.version!=1||!accepted||accepted->contact.actor_id!=actor||accepted->contact.provider_actor_id!=start->contact.provider_actor_id||accepted->duration_ticks!=1||!action_number||!start_number||*action_number>=*start_number||!header(common,accepted->fact_id,personal_appointment_accepted_kind)||!header(common,start->fact_id,personal_appointment_started_kind)||!before(common,accepted->fact_id,start->fact_id)||*action_number<=*appointment_detail::serial(accepted->fact_id,personal_appointment_accepted_kind,common.state().next_instance_id)||start->contact.tick<accepted->earliest_tick||start->contact.tick>accepted->latest_tick)return fail("PersonalAppointmentActionSourceMismatch",action_id);
    PersonalAppointmentActionSource source;source.source_identity=common.state().identity;source.actor_id=actor;source.appointment_id=accepted->fact_id;source.action_id=action_id;source.started_fact_id=start->fact_id;source.contact=start->contact;source.start_tick=start->contact.tick;
    const PersonalAppointmentFinished* finish=nullptr;for(const auto& row:state.finished.rows())if(row.second.action_id==action_id){if(finish)return fail("DuplicatePersonalAppointmentCompletion",action_id);finish=&row.second;}
    if(finish){if(current||finish->appointment_id!=accepted->fact_id||finish->start_fact_id!=start->fact_id||finish->tick!=start->contact.tick+1||finish->tick>common.tick()||!header(common,finish->fact_id,personal_appointment_finished_kind)||!before(common,start->fact_id,finish->fact_id))return fail("PersonalAppointmentCompletionSourceMismatch",action_id);
        if(finish->success?!finish->reason.empty():(finish->reason!="PersonalAppointmentParticipantUnavailable"&&finish->reason!="PersonalAppointmentMeetingChanged"))return fail("InvalidPersonalAppointmentReason",action_id);source.finished_fact_id=finish->fact_id;source.finished_tick=finish->tick;source.success=finish->success;source.reason=finish->reason;source.status=finish->success?"fulfilled":"interrupted";
    }else{const auto* person=common.actor(actor);const auto* provider=common.actor(start->contact.provider_actor_id);
        if(!current||current->kind!=personal_appointment_action_kind||current->actor_id!=actor||current->start_tick!=start->contact.tick||current->remaining_ticks!=1||current->participants!=std::vector<StableId>{actor,start->contact.provider_actor_id}||common.tick()!=start->contact.tick||!person||!provider||person->action_id!=action_id||provider->action_id!=action_id)return fail("PersonalAppointmentActionMismatch",action_id);source.status="active";source.remaining_ticks=current->remaining_ticks;
    }return {true,std::move(source),{}};
}
Outcome<std::optional<PersonalAppointmentActionSource>> query_personal_appointment_completion(const CommonStore& common,const PersonalAppointmentState& state,const StableId& actor,const StableId& action,const ReceiptDetails& details,Integer completed_tick,const StableId&actual_result_id,const PersonalAppointmentTime2Context*exact){
    auto source=query_personal_appointment_action(common,state,actor,action,exact);if(!source.ok||!source.value)return source;const auto* advance=std::get_if<AdvanceDetails>(&details.data);const auto* completion=advance?advance->completed_actions.find(action):nullptr;
    if(!completion||source.value->status=="active"||(state.version==2?source.value->finished_tick>completed_tick:source.value->finished_tick!=completed_tick)||!completion->ok||completion->completed!=std::optional<bool>{true}||completion->success!=std::optional<bool>{source.value->success}||completion->code!=std::optional<StableId>{source.value->success?StableId{"PersonalAppointmentFulfilled"}:source.value->reason}||completion->already_completed||completion->task||completion->military||completion->family||completion->growth||!completion->military_field_order.empty())return fail("PersonalAppointmentCompletionReceiptMismatch",action);
    if(state.version==2){const auto*ended=state.finished.find(source.value->finished_fact_id);if(!ended||!ended->player_receipt||actual_result_id.empty())return fail("PersonalAppointmentActualCompletionResultRequired",action);const auto&binding=*ended->player_receipt;const auto*result=common.state().results.find(binding.request_actor_id+":"+std::to_string(binding.request_sequence));if(!result||!*result||(*result)->result_id!=binding.result_id||(*result)->revision!=binding.result_revision||(*result)->tick!=completed_tick||!(*result)->details||actual_result_id!=binding.result_id)return fail("PersonalAppointmentActualCompletionResultRequired",action);}
    return source;
}
}
